#!/usr/bin/env ruby
# frozen_string_literal: true

require "date"
require "fileutils"
require "yaml"

# X-48
module RelayCodegen
  GENERATOR_VERSION = "1"
  ROOT = File.expand_path("../../..", __dir__)
  SPEC = File.join(ROOT, "contracts/openapi/server.yaml")
  ERRORS = File.join(ROOT, "contracts/errors.yaml")
  OUT = File.expand_path("../lib/esuiss/relay/generated", __dir__)
  HEADER = "# Code generated by sdks/ruby/codegen/generate.rb from contracts/openapi/server.yaml. " \
           "DO NOT EDIT."
  VERBS = %w[get put post delete patch].freeze
  JSON_TYPES = ["application/json", "application/merge-patch+json"].freeze
  EXCLUDED_TAGS = %w[access messaging-inbound].freeze
  PUBLIC_PREFIXES = ["/v1/errors/", "/.well-known/"].freeze
  HIDDEN_HEADERS = %w[
    relay-version relay-beta idempotency-key dpop authorization relay-tenant relay-environment
    relay-csrf-token
  ].freeze
  TAKEN = %w[body idempotency_key request_options].freeze
  RESERVED = %w[
    __ENCODING__ __LINE__ __FILE__ BEGIN END alias and begin break case class def defined do else
    elsif end ensure false for if in module next nil not or redo rescue retry return self super then
    true undef unless until when while yield
  ].freeze

  Param = Struct.new(:name, :location, :required, :ident, :csv, keyword_init: true)
  Operation = Struct.new(
    :id, :verb, :path, :summary, :path_params, :params, :body, :body_required, :content_type,
    :idempotent, :response, :paginated,
    keyword_init: true
  )

  # Loads contract files once and follows `$ref` pointers relative to the file holding them.
  class Resolver
    def initialize
      @files = {}
    end

    def load(path)
      @files[path] ||= YAML.safe_load_file(path, permitted_classes: [Date, Time], aliases: true)
    end

    def deref(node, base)
      64.times do
        return [node, base] unless node.is_a?(Hash) && node.key?("$ref")

        file, pointer = node["$ref"].split("#", 2)
        base = File.expand_path(file, File.dirname(base)) unless file.nil? || file.empty?
        node = pointer.to_s.split("/").reject(&:empty?).reduce(load(base)) do |acc, part|
          acc.fetch(part.gsub("~1", "/").gsub("~0", "~"))
        end
      end
      raise "reference chain too deep"
    end

    def properties(schema, base, depth = 0)
      schema, base = deref(schema, base)
      return {} if !schema.is_a?(Hash) || depth > 16

      merged = {}
      Array(schema["allOf"]).each { |part| merged.merge!(properties(part, base, depth + 1)) }
      merged.merge(schema["properties"] || {})
    end
  end

  # Turns the contract into the operations module and the constants file.
  class Generator
    def initialize
      @resolver = Resolver.new
    end

    def run
      FileUtils.mkdir_p(OUT)
      File.write(File.join(OUT, "api.rb"), api_file)
      File.write(File.join(OUT, "operations.rb"), operations_file)
    end

    private

    def spec
      @resolver.load(SPEC)
    end

    def api_file
      errors = YAML.safe_load_file(ERRORS, permitted_classes: [Date, Time], aliases: true)
      rows = errors.fetch("codes").map do |entry|
        "        #{entry.fetch('code').inspect} => { family: #{entry.fetch('family').inspect}, " \
          "status: #{Integer(entry.fetch('status'))}, retryable: #{entry.fetch('retryable') == true} },"
      end
      <<~RUBY
        # frozen_string_literal: true

        #{HEADER}

        module Esuiss
          module Relay
            module Generated
              API_VERSION = #{spec.fetch('info').fetch('version').to_s.inspect}
              GENERATOR_VERSION = #{GENERATOR_VERSION.inspect}
              ERROR_CODES = {
        #{rows.join("\n")}
              }.freeze
            end
          end
        end
      RUBY
    end

    def operations_file
      methods = operations.map { |op| render(op) }.join("\n")
      <<~RUBY
        # frozen_string_literal: true

        #{HEADER}

        module Esuiss
          module Relay
            module Generated
              # The operations of the Relay server API, one method per operationId.
              module Operations
        #{methods.chomp}
              end
            end
          end
        end
      RUBY
    end

    def operations
      root_security = spec["security"]
      ops = []
      spec.fetch("paths").each do |path, item|
        item.each do |verb, op|
          next unless VERBS.include?(verb) && included?(path, op, root_security)

          built = build(path, verb, op, Array(item["parameters"]))
          ops << built if built
        end
      end
      ops
    end

    def included?(path, op, root_security)
      return false if path.start_with?("/inbound/")
      return false if EXCLUDED_TAGS.include?(Array(op["tags"]).first)

      security = op.fetch("security", root_security) || []
      return path.start_with?(*PUBLIC_PREFIXES) if security.empty?

      security.any? { |requirement| requirement.key?("access_bearer") }
    end

    def build(path, verb, op, item_params)
      resolved = resolve_params(item_params + Array(op["parameters"]))
      body = request_body(op)
      return nil if body == :unsupported

      response, paginated = response_kind(op, resolved)
      Operation.new(
        id: op.fetch("operationId"),
        verb: verb,
        path: path,
        summary: op["summary"].to_s.gsub(/\s+/, " ").strip,
        path_params: path.scan(/\{([^}]+)\}/).flatten.map { |name| [name, ident(name)] },
        params: visible_params(resolved),
        body: !body.nil?,
        body_required: body.is_a?(Hash) && body[:required],
        content_type: body.is_a?(Hash) ? body[:content_type] : nil,
        idempotent: resolved.any? { |p| p["in"] == "header" && p["name"].casecmp?("idempotency-key") },
        response: response,
        paginated: paginated
      )
    end

    def resolve_params(raw)
      by_key = {}
      raw.each do |param|
        node, base = @resolver.deref(param, SPEC)
        schema, = @resolver.deref(node["schema"] || {}, base)
        by_key[[node.fetch("name"), node.fetch("in")]] = node.merge("_schema" => schema)
      end
      by_key.values
    end

    def visible_params(resolved)
      params = resolved.filter_map do |param|
        location = param["in"]
        next if %w[path cookie].include?(location)
        next if location == "header" && HIDDEN_HEADERS.include?(param["name"].downcase)

        schema = param["_schema"].is_a?(Hash) ? param["_schema"] : {}
        csv = schema["type"] == "array" && param["explode"] == false
        Param.new(name: param["name"], location: location, required: param["required"] == true,
                  ident: ident(param["name"]), csv: csv)
      end
      idents = params.map(&:ident)
      raise "duplicate parameter names: #{idents}" if idents.uniq.size != idents.size

      params
    end

    def request_body(op)
      return nil unless op["requestBody"]

      body, = @resolver.deref(op["requestBody"], SPEC)
      content_type = JSON_TYPES.find { |type| body.fetch("content", {}).key?(type) }
      return :unsupported unless content_type

      { required: body["required"] == true, content_type: content_type }
    end

    def response_kind(op, resolved)
      codes = (op["responses"] || {}).keys.map(&:to_s).grep(/\A2\d\d\z/).sort
      contents = codes.to_h do |code|
        response, base = @resolver.deref(op["responses"][code] || op["responses"][code.to_i], SPEC)
        [code, [response.is_a?(Hash) ? (response["content"] || {}) : {}, base]]
      end
      if contents.values.any? { |content, _| content.key?("application/json") }
        [:json, paginated?(contents["200"], resolved)]
      elsif contents.values.any? { |content, _| content.keys.any? { |type| type.start_with?("text/") } }
        [:text, false]
      else
        [:none, false]
      end
    end

    def paginated?(content_and_base, resolved)
      return false unless content_and_base
      return false unless resolved.any? { |p| p["in"] == "query" && p["name"] == "starting_after" }

      content, base = content_and_base
      media = content["application/json"]
      return false unless media

      props = @resolver.properties(media["schema"], base)
      %w[data has_more next_cursor].all? { |name| props.key?(name) }
    end

    def ident(name)
      id = name.gsub(/([a-z0-9])([A-Z])/, '\1_\2').downcase.gsub(/[^a-z0-9]+/, "_").gsub(/\A_+|_+\z/, "")
      id = "p_#{id}" if id.match?(/\A\d/)
      id = "#{id}_param" if RESERVED.include?(id) || TAKEN.include?(id)
      id
    end

    def method_name(operation_id)
      operation_id.gsub(/([A-Z]+)([A-Z][a-z])/, '\1_\2').gsub(/([a-z0-9])([A-Z])/, '\1_\2').downcase
    end

    def render(op)
      lines = []
      lines << "        # #{op.summary}" unless op.summary.empty?
      lines << "        def #{method_name(op.id)}(#{signature(op).join(', ')})"
      lines.concat(call(op).map { |line| "          #{line}" })
      lines << "        end"
      "#{lines.join("\n")}\n"
    end

    def signature(op)
      args = op.path_params.map { |_, id| id }
      args << (op.body_required ? "body" : "body = nil") if op.body
      required, optional = op.params.partition(&:required)
      args.concat(required.map { |p| "#{p.ident}:" })
      args.concat(optional.map { |p| "#{p.ident}: nil" })
      args << "idempotency_key: nil" if op.idempotent
      args << "request_options: {}"
      args
    end

    def call(op)
      args = ["method: :#{op.verb}", "path: #{path_literal(op)}"]
      args << "query: #{hash_literal(op.params.select { |p| p.location == 'query' })}"
      args << "headers: #{hash_literal(op.params.select { |p| p.location == 'header' })}"
      args.concat(perform_args(op)) unless op.paginated
      args << "request_options: request_options"
      lines = args.map { |arg| "  #{arg}," }
      lines[-1] = lines[-1].delete_suffix(",")
      ["#{op.paginated ? 'paginate' : 'perform'}(", *lines, ")"]
    end

    def perform_args(op)
      args = ["body: #{op.body ? 'body' : 'nil'}"]
      args << "content_type: #{op.content_type.inspect}" if op.content_type
      args << "idempotent: #{op.idempotent}"
      args << "idempotency_key: idempotency_key" if op.idempotent
      args << "response: :#{op.response}"
    end

    def path_literal(op)
      path = op.path.dup
      op.path_params.each { |name, id| path = path.gsub("{#{name}}", "\#{segment(#{id})}") }
      "\"#{path}\""
    end

    def hash_literal(params)
      return "{}" if params.empty?

      pairs = params.map { |p| "#{p.name.inspect} => #{p.csv ? "csv(#{p.ident})" : p.ident}" }
      "{ #{pairs.join(', ')} }"
    end
  end
end

RelayCodegen::Generator.new.run if $PROGRAM_NAME == __FILE__
